public class Account {

    int accountNumber;
    double accountBalance;

    private static double interestRate = 0.05;

    public Account(double accountBalance, int accountNumber) {
        this.accountBalance = accountBalance;
        this.accountNumber = accountNumber;
    }
    public Account() {

    }

    public static double getInterestRate() {
        return interestRate;
    }

    public static void setInterestRate(double interestRate) {
        Account.interestRate = interestRate;
    }

    public int getAccountNumber() {
        return accountNumber;
    }

    public double getAccountBalance() {
        return accountBalance;
    }

    public void setAccountNumber(int accountNumber) {
        this.accountNumber = accountNumber;
    }

    public void setAccountBalance(double accountBalance) {
        this.accountBalance = accountBalance;
    }

    public void addInterest() {
        accountBalance *= (1 + interestRate);
    }

    public boolean withdraw(double amount) {
        if (amount <= accountBalance) {
            accountBalance -= amount;
            System.out.println(" now has a balance of " + accountBalance);
            return true;
        } else {
            System.out.println(" has insufficient funds for this withdrawal");
            return false;
        }
    }

    public boolean withdraw() {
        return withdraw(20);
    }


    @Override
    public String toString() {
        return "Account{" +
                "accountNumber=" + accountNumber +
                ", accountBalance=" + accountBalance +
                '}';
    }

    @Override
    public int hashCode() {
        return super.hashCode();
    }

    @Override
    public boolean equals(Object obj) {
        return super.equals(obj);
    }
}

import exception.DodgyNameException;

import java.util.Objects;

public class Account {

    private String name;
    private double balance;
    private AccountType accountType;

    private static double interestRate = 0.05;

    public Account(double balance, String name, AccountType accountType) throws DodgyNameException {
        setName(name);
        this.balance = balance;
        this.accountType = accountType;
    }

    public Account() {
    }

    public static double getInterestRate() {
        return interestRate;
    }

    public static void setInterestRate(double interestRate) {
        Account.interestRate = interestRate;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) throws DodgyNameException {
        if (name == null || name.trim().isEmpty()) {
            throw new DodgyNameException("Account name cannot be empty");
        }
        if ("Fingers".equalsIgnoreCase(name.trim())) {
            throw new DodgyNameException("Name 'Fingers' is not allowed");
        }
        this.name = name.trim();
    }

    public double getBalance() {
        return balance;
    }

    // Backward-compatible alias for older test code.
    public double getAccountBalance() {
        return balance;
    }

    public void setBalance(double balance) {
        this.balance = balance;
    }

    public void setAccountBalance(double accountBalance) {
        this.balance = accountBalance;
    }

    public AccountType getAccountType() {
        return accountType;
    }

    public void setAccountType(AccountType accountType) {
        this.accountType = accountType;
    }

    public void addInterest() {
        balance *= (1 + interestRate);
    }

    public boolean withdraw(double amount) {
        if (amount <= balance) {
            balance -= amount;
            System.out.println(name + " now has a balance of " + balance);
            return true;
        } else {
            System.out.println(name + " has insufficient funds for this withdrawal");
            return false;
        }
    }

    public boolean withdraw() {
        return withdraw(20);
    }

    @Override
    public String toString() {
        return "Account{" +
                "name='" + name + '\'' +
                ", balance=" + balance +
                ", accountType=" + accountType +
                '}';
    }

    @Override
    public int hashCode() {
        return Objects.hash(name, accountType);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (!(obj instanceof Account)) {
            return false;
        }
        Account other = (Account) obj;
        return Objects.equals(name, other.name) && accountType == other.accountType;
    }
}

import java.util.ArrayList;
import java.util.List;

public class TestAccount {
    public static void main(String[] args) {

        Account[] accounts = new Account[5];
        accounts[0] = new Account(1000.0, 1);
        accounts[1] = new Account(2000.0, 2);
        accounts[2] = new Account(1500.0, 3);
        accounts[3] = new Account(1500.0, 4);
        accounts[4] = new Account(2500.0, 5);

        Account.setInterestRate(0.07);

        for (int i = 0; i < accounts.length; i++) {
            System.out.println("Account: " + accounts[i]);
            accounts[i].addInterest();
            System.out.println("Balance after interest: " + accounts[i].getAccountBalance());
            System.out.println();
        }

        System.out.println(accounts[2].equals(accounts[3]) ? "account 2 and 3 are equal" : "account 2 and 3 are not equal");
        System.out.println(accounts[2].equals(accounts[4]) ? "account 2 and 4 are equal" : "account 2 and 4 are not equal");

        accounts[0].withdraw(100);
        accounts[1].withdraw();
        accounts[2].withdraw(2500);

        // CarParts enum test
        CarParts part = CarParts.WHEELS;
        if (part == CarParts.ENGINE) {
            System.out.println("The part is an engine");
        } else {
            System.out.println("The part is not an engine");
        }

        // List usage
        List<Account> acc = new ArrayList<>();
        acc.add(accounts[0]);
        acc.add(accounts[1]);
        System.out.println("Accounts in list: " + acc);
    }
}

import exception.DodgyNameException;

import java.util.ArrayList;
import java.util.List;

public class TestAccount {
    public static void main(String[] args) {

        Account[] accounts = new Account[5];
        accounts[0] = createAccount(1000.0, "Alice", AccountType.CHECKING);
        accounts[1] = createAccount(2000.0, "Bob", AccountType.CHECKING);
        accounts[2] = createAccount(1500.0, "Charlie", AccountType.SAVING);
        accounts[3] = createAccount(1500.0, "Diana", AccountType.SAVING);
        accounts[4] = createAccount(2500.0, "Eve", AccountType.CREDIT_CARD);

        Account.setInterestRate(0.07);

        for (int i = 0; i < accounts.length; i++) {
            if (accounts[i] == null) {
                continue;
            }
            System.out.println("Account: " + accounts[i]);
            accounts[i].addInterest();
            System.out.println("Balance after interest: " + accounts[i].getBalance());
            System.out.println();
        }

        System.out.println(accounts[2].equals(accounts[3]) ? "account 2 and 3 are equal" : "account 2 and 3 are not equal");
        System.out.println(accounts[2].equals(accounts[4]) ? "account 2 and 4 are equal" : "account 2 and 4 are not equal");

        accounts[0].withdraw(100);
        accounts[1].withdraw();
        accounts[2].withdraw(2500);

        // CarParts enum test
        CarParts part = CarParts.WHEELS;
        if (part == CarParts.ENGINE) {
            System.out.println("The part is an engine");
        } else {
            System.out.println("The part is not an engine");
        }

        // List usage
        List<Account> acc = new ArrayList<>();
        acc.add(accounts[0]);
        acc.add(accounts[1]);
        System.out.println("Accounts in list: " + acc);
    }

    private static Account createAccount(double balance, String name, AccountType type) {
        try {
            return new Account(balance, name, type);
        } catch (DodgyNameException e) {
            System.out.println(e.getMessage());
            return null;
        }
    }
}
